// fetches spec fixtures + generates the runtime data tables (entities, unicode).
// run: npm run fixtures:fetch. needs network for the first three steps.
// generated files are committed so CI never needs this script to pass.
import { writeFileSync, mkdirSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const fixtures = join(root, 'tests', 'fixtures')
mkdirSync(fixtures, { recursive: true })

async function get(url) {
  const res = await fetch(url)
  if (!res.ok) throw new Error(`${res.status} ${url}`)
  return res.text()
}

// 1. CommonMark 0.31.2 spec examples (the 652)
const specJson = await get('https://spec.commonmark.org/0.31.2/spec.json')
const spec = JSON.parse(specJson)
if (!Array.isArray(spec) || spec.length < 600)
  throw new Error(`spec.json looks wrong: ${spec.length} examples`)
writeFileSync(join(fixtures, 'commonmark-0.31.2.json'), JSON.stringify(spec, null, 1))
console.log(`commonmark-0.31.2.json: ${spec.length} examples`)

// 2. GFM extension examples from cmark-gfm's spec.txt.
// extension sections only -- the GFM spec's core sections are based on
// CommonMark 0.29 and disagree with 0.31.2 in a few places
const specTxt = await get('https://raw.githubusercontent.com/github/cmark-gfm/master/test/spec.txt')
const gfmExamples = []
const tagCounts = {}
let section = ''
let i = 0
const lines = specTxt.split('\n')
while (i < lines.length) {
  const line = lines[i]
  const heading = /^(#{1,3})\s+(.*)$/.exec(line)
  if (heading) section = heading[2].trim()
  const start = /^(`{16,})\s*example\s*(\S*)\s*$/.exec(line)
  if (start) {
    const [, fence, tag = ''] = start
    let end = i + 1
    while (end < lines.length && lines[end] !== fence) end++
    if (end >= lines.length) throw new Error(`unterminated example at line ${i}`)
    const body = lines.slice(i + 1, end)
    const dot = body.indexOf('.')
    if (dot === -1) throw new Error(`example without '.' separator at line ${i}`)
    const markdown = body.slice(0, dot).join('\n')
    const html = body.slice(dot + 1).join('\n')
    tagCounts[tag || 'core'] = (tagCounts[tag || 'core'] ?? 0) + 1
    // cmark-gfm tags tasklist examples "disabled" (why, idk) and we skip tagfilter
    const normalizedTag = tag === 'disabled' ? 'tasklist' : tag
    if (normalizedTag && normalizedTag !== 'tagfilter') {
      gfmExamples.push({ section, extension: normalizedTag, markdown, html })
    }
    i = end
  }
  i++
}
writeFileSync(join(fixtures, 'gfm-extensions.json'), JSON.stringify(gfmExamples, null, 1))
console.log(
  `gfm-extensions.json: ${gfmExamples.length} examples, tags: ${JSON.stringify(tagCounts)}`,
)

// 3. HTML5 named entity table -> generated TS
const entitiesJson = await get('https://html.spec.whatwg.org/entities.json')
const rawEntities = JSON.parse(entitiesJson)
const entries = Object.entries(rawEntities)
  .filter(([k]) => k.startsWith('&') && k.endsWith(';'))
  .map(([k, v]) => [k.slice(1, -1), v.characters])
  .sort(([a], [b]) => (a < b ? -1 : 1))
if (entries.length < 2000) throw new Error(`entities.json looks wrong: ${entries.length} entries`)
const entitiesTs = `// generated by scripts/fetch-fixtures.mjs from https://html.spec.whatwg.org/entities.json
// keys are entity names without & and with ; -- the semicolon is required by CommonMark 0.31.2 §2.3
export const namedEntities: Readonly<Record<string, string>> = {
${entries.map(([k, v]) => `  '${k}': ${JSON.stringify(v)},`).join('\n')}
}
`
writeFileSync(join(root, 'src', 'entities.generated.ts'), entitiesTs)
console.log(`entities.generated.ts: ${entries.length} entities`)

// 4b. case-fold overrides: code points where full case folding differs from
// String#toLowerCase (ligatures, sharp s, ...). CommonMark says "case fold",
// toLowerCase isn't it.
try {
  const cf = await get('https://www.unicode.org/Public/UCD/latest/ucd/CaseFolding.txt')
  const overrides = []
  for (const line of cf.split('\n')) {
    const m = /^([0-9A-F]+); ([CFS]); ([^;]+);/.exec(line)
    if (!m) continue
    const cp = parseInt(m[1] ?? '', 16)
    const status = m[2]
    const folded = (m[3] ?? '')
      .trim()
      .split(/\s+/)
      .map((h) => String.fromCodePoint(parseInt(h, 16)))
      .join('')
    const lower = String.fromCodePoint(cp).toLowerCase()
    // prefer the full (F) mapping when present; C/S only when F is absent
    const existing = overrides.find((o) => o[0] === cp)
    if (status === 'F' || !existing) {
      if (existing) existing[1] = folded
      else if (folded !== lower) overrides.push([cp, folded])
    }
  }
  const fmtFolds = overrides
    .map(([cp, f]) => `[0x${cp.toString(16)}, ${JSON.stringify(f)}],`)
    .join('\n  ')
  const foldTs = `// generated by scripts/fetch-fixtures.mjs from CaseFolding.txt
// full case folding where it differs from toLowerCase (spec 0.31.2 §6.6 "case fold")
export const caseFoldOverrides: ReadonlyArray<readonly [number, string]> = [
  ${fmtFolds}
]
`
  writeFileSync(join(root, 'src', 'case-folds.generated.ts'), foldTs)
  console.log(`case-folds.generated.ts: ${overrides.length} overrides`)
} catch (err) {
  console.log(`case folding skipped: ${err instanceof Error ? err.message : err}`)
}

// 5. unicode punctuation (all P categories) + Zs whitespace ranges -> generated TS
// node's ICU regexes are the source of truth at dev time; runtime binary-searches
const punctuation = []
const whitespace = []
for (let cp = 0; cp <= 0x10ffff; cp++) {
  const ch = String.fromCodePoint(cp)
  if (/\p{P}|\p{S}/u.test(ch)) pushRange(punctuation, cp)
  if (/\p{Zs}/u.test(ch)) pushRange(whitespace, cp)
}
function pushRange(ranges, cp) {
  const last = ranges[ranges.length - 1]
  if (last && last[1] === cp - 1) last[1] = cp
  else ranges.push([cp, cp])
}
const fmt = (ranges) =>
  ranges
    .map(([a, b]) => `[0x${a.toString(16)}, 0x${b.toString(16)}],`)
    .join(String.fromCharCode(10) + '  ')
const unicodeTs = `// generated by scripts/fetch-fixtures.mjs using node ICU \\p{P} and \\p{Zs}
// spec 0.31.2 §2.2: unicode whitespace = Zs + \\t \\n \\f \\r (vtab is NOT whitespace in CommonMark)
// spec 0.31.2 §2.2: flanking "unicode punctuation" = P or S categories (symbols count)
export const punctuationRanges: ReadonlyArray<readonly [number, number]> = [
  ${fmt(punctuation)}
]

export const spaceSeparatorRanges: ReadonlyArray<readonly [number, number]> = [
  ${fmt(whitespace)}
]
`
writeFileSync(join(root, 'src', 'unicode-tables.generated.ts'), unicodeTs)
console.log(
  `unicode-tables.generated.ts: ${punctuation.length} punct ranges, ${whitespace.length} Zs ranges`,
)
